package com.bank.loan.service;

import com.bank.loan.client.CreditBureauClient;
import com.bank.loan.repository.LoanRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class BadLoanService {
    private static final Logger log = LoggerFactory.getLogger(BadLoanService.class);
    private final CreditBureauClient bureau;
    private final LoanRepository loanRepo;

    public BadLoanService(CreditBureauClient bureau, LoanRepository loanRepo) {
        this.bureau = bureau; this.loanRepo = loanRepo;
    }

    // BAD: the external call runs INSIDE the transaction, pinning the
    // pooled connection for ~2.5s of idle-in-transaction time per request.
    @Transactional
    public void approve(String loanId, String pan) {
        int score = bureau.fetchScore(pan);          // connection held, DB idle 2.5s
        loanRepo.markApproved(loanId, score);         // only now does any DB work happen
        log.info("Loan {} approved with score {}", loanId, score);
    }
}
