package com.bank.loan.service;

import com.bank.loan.client.CreditBureauClient;
import com.bank.loan.repository.LoanRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class GoodLoanService {
    private static final Logger log = LoggerFactory.getLogger(GoodLoanService.class);
    private final CreditBureauClient bureau;
    private final LoanRepository loanRepo;

    public GoodLoanService(CreditBureauClient bureau, LoanRepository loanRepo) {
        this.bureau = bureau; this.loanRepo = loanRepo;
    }

    // GOOD: external call happens OUTSIDE the transaction. No connection is
    // borrowed during the slow bureau call.
    public void approve(String loanId, String pan) {
        int score = bureau.fetchScore(pan);   // slow, but NO DB connection held
        persist(loanId, score);                // short transaction, commits in ms
    }

    @Transactional
    protected void persist(String loanId, int score) {
        loanRepo.markApproved(loanId, score);  // borrow → quick update → commit → return
        log.info("Loan {} approved with score {} (short txn)", loanId, score);
    }
}
